%[text] Exercise 1
x1=0:0.1:4*pi;
y1=sin(x1);

x2=0:1.0:4*pi;
y2=sin(x2+1);

plot(x1, y1,'-k','LineWidth',1.5)     %[output:767a391a]
hold on %[output:767a391a]
plot(x2, y2,'--b','LineWidth',1.5) %[output:767a391a]
hold off %[output:767a391a]
xlabel('x');ylabel('y') %[output:767a391a]
title('sin(x) and sin(x+1)') %[output:767a391a]
grid on %[output:767a391a]
%[text] Exercise 2
Z = (4.*X.^2 + Y.^2 + X - 1) .* exp(-X.^2 - Y.^2);
surf(X, Y, Z);
xlabel('X');
ylabel('Y');
zlabel('Z');
title('Surface plot of z = (4x^2 + y^2 + x - 1)e^{-x^2-y^2}');

